#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <string.h>
#include <stdlib.h>
#include <linux/fcntl.h>

int main() {
    int fd;
    char pipe_name[] = "/tmp/pipe";
    char data[] = "Hello, World!";
    char read_data[100];
    int ret;

    // Create a named pipe
    mkfifo(pipe_name, 0666);

    // Open the pipe for writing
    fd = open(pipe_name, O_WRONLY);
    if (fd == -1) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    // Write data to the pipe
    ret = write(fd, data, strlen(data));
    if (ret == -1) {
        perror("write");
        exit(EXIT_FAILURE);
    }

    // Close the pipe
    close(fd);

    // Open the pipe for reading
    fd = open(pipe_name, O_RDONLY);
    if (fd == -1) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    // Read data from the pipe
    ret = read(fd, read_data, sizeof(read_data));
    if (ret == -1) {
        perror("read");
        exit(EXIT_FAILURE);
    }

    // Print the data read from the pipe
    printf("Data read from pipe: %s\n", read_data);

    // Close the pipe
    close(fd);

    // Remove the pipe
    unlink(pipe_name);

    return 0;
}
```

